import {Port,materials} from '../../core/index.js';import {portQuaternion} from '../../modeling/parts.js';import {THREE,box} from './geometry.js';import {spec} from './dimensions.js';
export function grove(host){const frame=new THREE.Group();frame.name='Original U031 red actual HY2.0 receiving socket';frame.position.fromArray(spec.grove.position);frame.quaternion.copy(portQuaternion('bottom'));host.body.add(frame);const red=materials.plastic(0xad2d3c,{roughness:.7}),metal=materials.metal(0xb3b6a5,{roughness:.43}),parts=[],walls=[],contacts=[],returns=[],feet=[],tails=[],b=(size,p,name,mat=red)=>{const o=box(frame,size,p,mat,'U031 Grove '+name);parts.push(o);return o;};for(const sign of[-1,1]){walls.push(b([.7,7.6,5.2],[sign*4.65,-3.8,0],'real receiving sidewall'));walls.push(b([.65,7.6,.65],[sign*3.98,-3.8,2.25],'real upper retaining rail'));}const floor=b([8.6,7.6,.6],[0,-3.8,-2.3],'real socket floor'),back=b([8.6,.7,4.6],[0,-7.25,.3],'deep actual dielectric insertion stop'),latch=b([3.8,1.3,.5],[0,-4.7,2.25],'real internal retaining latch'),seat=b([8.6,1.2,.8],[0,-8.1,-2.2],'deep carrier bridge rests on actualPCB');for(let i=0;i<4;i++){const x=(i-1.5)*2;contacts.push(b([.42,5.8,.42],[x,-4,-.6],'actual retained contact '+(i+1),metal));returns.push(b([.42,.6,2.2],[x,-7.2,-1.5],'actual conductor return '+(i+1),metal));feet.push(b([.42,1.4,.42],[x,-7.8,-2.4],'retained conductor foot '+(i+1),metal));tails.push(b([.42,.42,1.8],[x,-8.3,-3.1],'actual through-board solder tail '+(i+1),metal));}const port=host.add(new Port({id:'grove',label:'Original U031 J1 · HY2.0-4P',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pinGrid:{cols:4,rows:1,pitch:2,center:[0,-.6],order:col=>col+1},pins:spec.grove.pins.map((name,i)=>({n:i+1,name})),meta:{role:'visual-connector',face:'bottom',numbering:'Original J1 schematic/rear legend SCL,SDA,VCC,GND;literal contact label only,no automatic wire color/electrical routing.',scope:'Real4contact receiver/cable mechanics only;no NFC,UID,I2C,address,RF,firmware or sensor output.'}}));return{frame,parts,walls,floor,back,latch,seat,contacts,returns,feet,tails,port};}
